    public static Icon forFile(java.io.File file, boolean expanded) {
        if (file == null) return getIcon("document");
        if (file.isDirectory()) return getIcon(expanded ? "folder-open" : "folder");

        String name = file.getName().toLowerCase();

        
        String byName = NAME_MAP.get(name);
        if (byName != null) return getIcon(byName);

        
        int dot = name.lastIndexOf('.');
        if (dot != -1) {
            String iconName = EXT_MAP.get(name.substring(dot + 1));
            if (iconName != null) return getIcon(iconName);
        }

 
        return getIcon("document");
    }


    public static Icon getIcon(String name) {
        return CACHE.computeIfAbsent(name, MaterialIconLoader::decode);
    }


    private static Icon decode(String name) {
        String b64 = PNG_DATA.getOrDefault(name, PNG_DATA.get("document"));
        if (b64 == null) return fallback(name);
        try {
            byte[] bytes = Base64.getDecoder().decode(b64);
            BufferedImage img = ImageIO.read(new ByteArrayInputStream(bytes));
            return new ImageIcon(img);
        } catch (Exception e) {
            return fallback(name);
        }
    }

    private static Icon fallback(String name) {
        
        java.awt.image.BufferedImage img =
            new java.awt.image.BufferedImage(16, 16, java.awt.image.BufferedImage.TYPE_INT_ARGB);
        java.awt.Graphics2D g = img.createGraphics();
        g.setColor(new java.awt.Color(120, 120, 130));
        g.fillRoundRect(1, 1, 14, 14, 3, 3);
        g.setColor(java.awt.Color.WHITE);
        g.setFont(new java.awt.Font("SansSerif", java.awt.Font.BOLD, 7));
        String lbl = name.isEmpty() ? "?" : name.substring(0, 1).toUpperCase();
        g.drawString(lbl, 5, 11);
        g.dispose();
        return new ImageIcon(img);
    }
